// The range read deliberately starts ONE ROW EARLY: the Sheets node treats the
// first row of an explicit A1 range as the column header. On the first batch
// that row is the real header ("user_id"); on every later batch it is the last
// already-processed user. Either way it is not data, so nothing is lost.
//
// Each remaining item carries exactly one cell: the user ID. The key varies
// between batches (it is whatever the "header" row contained), so grab the
// value positionally instead of by name, ignoring n8n's row_number metadata.
//
// No filtering here — every row read must become exactly one item, so that the
// checkpoint (advanced by rows read) can never drift from what was attempted.
// Blank or malformed rows simply fail at the Discord node and land in the
// Failures tab.
return $input.all().map((item) => {
  const values = Object.entries(item.json)
    .filter(([key]) => key !== 'row_number')
    .map(([, v]) => v);
  const raw = values[0];
  const user_id = typeof raw === 'number' ? raw.toFixed(0) : String(raw ?? '').trim();
  return { json: { user_id } };
});

// Runs once, on the Loop's `done` output, which carries the accumulated
// Discord results from every cycle in original order (1:1 with Normalize IDs —
// onError=continue means failed items still emit exactly one item).
//
// The checkpoint advances by ROWS READ from the sheet, not by successes, so a
// bad row can never wedge the run into re-reading the same batch forever.
// Failed users are recorded in the Failures tab instead and can be re-run
// later.
const results = $input.all();
const sources = $('Normalize IDs').all();
const rowsRead = $('Read User Batch').all().length;
const checkpoint = parseInt($('Read Config').first().json.value, 10) || 0;

const failures = [];
results.forEach((item, i) => {
  if (item.json.error !== undefined) {
    failures.push({
      user_id: sources[i] ? sources[i].json.user_id : 'unknown',
      error: typeof item.json.error === 'string' ? item.json.error : JSON.stringify(item.json.error),
    });
  }
});

return [{
  json: {
    timestamp: new Date().toISOString(),
    checkpoint_before: checkpoint,
    rows_read: rowsRead,
    attempted: results.length,
    succeeded: results.length - failures.length,
    failed: failures.length,
    new_checkpoint: checkpoint + rowsRead,
    failures,
  },
}];

// Turns the summary's failures array into one item per failed user.
// If nothing failed this returns an empty array and the Append Failures node
// simply never executes — zero Sheets calls wasted.
const s = $input.first().json;
return (s.failures || []).map((f) => ({
  json: {
    timestamp: s.timestamp,
    user_id: f.user_id,
    error: f.error,
    checkpoint_batch: s.checkpoint_before,
  },
}));
